// CSD_RATIONALE_BEGIN
// Best result: attempt 18 at 58.3% used 6-free-token prefix → OpenConstrainedSpan
// → CloseSpanWithinBudget. Attempts 21 and 22 regressed because the guidance
// actively harmed generation (attempt 21 discouraged COUNT(DISTINCT); attempt 22
// lost the format-focus and schema-grounding from attempt 18).
//
// Observed rollout failures:
//   1. "Find the number of distinct type of pets" →
//      model emits SELECT DISTINCT pettype instead of COUNT(DISTINCT pettype).
//      Root cause: model conflates "distinct type" with SELECT DISTINCT.
//      Fix: add "use COUNT(DISTINCT col) when counting distinct values".
//   2. "What are the number of concerts..." →
//      model appends AS number_of_concerts alias, breaking exact-match.
//      Root cause: model adds explanatory aliases unprompted.
//      Fix: add "never add column aliases (no AS after column names)".
//   3. "List all student details..." →
//      model hallucinates a massive column list with repetitive aliases.
//      Partial fix: schema-grounding ("use only schema names") already in attempt 18.
//
// Strategy: preserve attempt 18's structure EXACTLY. Improve only the guidance
// string to add (a) COUNT(DISTINCT) rule and (b) no-column-alias rule while
// retaining the three elements that worked in attempt 18:
//   – "Generate exactly: SQL: <<...>>"  (format)
//   – "Use only table and column names from the schema"  (schema grounding)
//   – "Output nothing else"  (prevents reasoning prefix)
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   Phase 1 (free loop): insideConstrainedOut is set true only when
//   RenderedEndsWith(generated,"<<") holds after appending next, simultaneously
//   setting currentConstrainedOut:=[]; parser.IsValidPrefix([]) holds by precondition.
//   If insideConstrained is true on entry the loop condition !insideConstrainedOut
//   is immediately false and the invariant is inherited from the precondition.
//   Phase 2 (OpenConstrainedSpan): postcondition gives insideConstrainedOut=true,
//   currentConstrainedOut=[], and parser.IsValidPrefix([]) holds.
//   Phase 3 (CloseSpanWithinBudget): postcondition guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut) and
//   !insideConstrainedOut ==> currentConstrainedOut==[].
//
// progress: |generated| <= |generatedPrefix| + steps
//   Phase 1: each iteration increments steps by 1 and appends at most 1 token;
//   invariant is maintained per-iteration.
//   Phase 2: OpenConstrainedSpan appends exactly "<<" (1 token) and steps += 1.
//   Phase 3: CloseSpanWithinBudget postcondition gives
//   |generatedOut| <= |generated_entering_phase3| + remainingBudget; after
//   steps += remainingBudget we have steps = maxSteps, so
//   |generated| <= |generatedPrefix| + maxSteps. cost := steps <= maxSteps.
//   When maxSteps > 0: prefixBudget = min(6, maxSteps) >= 1 so Phase 1 takes
//   at least 1 step → cost >= 1 > 0.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  return;
}

// Guidance: keeps format-focus and schema-grounding from attempt 18 (58.3%);
// adds COUNT(DISTINCT) rule (fixes rollout 1) and no-alias rule (fixes rollout 2).
var guidance: string := "Generate exactly: SQL: <<sql_query>> where sql_query answers the question. When counting distinct or different values use COUNT(DISTINCT col), not SELECT DISTINCT. Never add column aliases (do not write AS after a column expression). Use only table and column names from the schema. Output nothing else.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

// Phase 1: Generate free prefix "SQL: " (at most 6 tokens).
var prefixBudget: nat := 6;
if prefixBudget > maxSteps {
  prefixBudget := maxSteps;
}

while steps < prefixBudget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases prefixBudget - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    insideConstrainedOut := true;
    currentConstrainedOut := [];
  }
}

// Phase 2: If not yet inside a constrained span, explicitly open one.
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate the constrained SQL query body and close the span.
if insideConstrainedOut && steps < maxSteps {
  var remainingBudget: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainingBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + remainingBudget;
}

cost := steps;

